// Des: Tests for export, report, backup and undo commands
// Flo: memory/tmp stores > build outputs > assert content
// I/O: rows and files > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const ex = @import("ct-comm-expo.zig"); const data = @import("st-stat-data.zig"); const acts = @import("ru-chat-acts.zig"); const snd = @import("ru-chat-send.zig"); const mock = @import("te-mock-page.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
test "export writes one json line per message and log row, quotes and unicode survive" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try sto.msgAdd("Mẹ", "them", "it's \"ok\" — chào", 5); try sto.logAdd(6, "info", "send", "sent"); const body = try ex.rowsOf(alo, &sto); var lines: u32 = 0; var itr = std.mem.splitScalar(u8, std.mem.trim(u8, body, "\n"), '\n'); while (itr.next()) |ln| { const val = try std.json.parseFromSliceLeaky(std.json.Value, alo, ln, .{}); try T.expect(val == .object); lines += 1; } try T.expectEqual(@as(u32, 2), lines); try T.expect(std.mem.find(u8, body, "chào") != null); }
test "report holds version, log lines and probe names but never chat text" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try sto.msgAdd("Mom", "them", "private words here", 1); try sto.logAdd(2, "info", "send", "PREVIEW Mom: «h:aabbccdd:7»"); const txt = try ex.reportText(alo, &sto, "{\"x\":1}", &.{ "chat1.json", "login.json" }); try T.expect(std.mem.startsWith(u8, txt, "za 0.2.0 report")); try T.expect(std.mem.find(u8, txt, "«h:aabbccdd:7»") != null); try T.expect(std.mem.find(u8, txt, "chat1.json") != null); try T.expect(std.mem.find(u8, txt, "private words") == null); }
test "backup is a complete copy that opens and has the same rows; backing up onto an existing file fails" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var pbuf: [160]u8 = undefined; const rel = try std.fmt.bufPrint(&pbuf, ".zig-cache/tmp/{s}/bk.db", .{tmpz.sub_path}); const path = try mock.absPath(T.allocator, T.io, rel); defer T.allocator.free(path); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); try sto.msgAdd("c", "them", "kept", 1); _ = try sto.sendBegin("c", "x", 1); try sto.sendDone("c", "x", 2); try sto.backup(path); const zpath = try T.allocator.dupeSentinel(u8, path, 0); defer T.allocator.free(zpath); var copy = try data.Stor.open(T.allocator, zpath); defer copy.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const tail = try copy.msgTail(aren.allocator(), "c", 5); try T.expectEqual(@as(usize, 1), tail.len); try T.expect(try copy.sendBegin("c", "x", 3) == .dup); try T.expectError(error.SqliStep, sto.backup(path)); }
test "last send is the newest sent row; none when nothing was sent" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expect((try sto.lastSend(aren.allocator())) == null); _ = try sto.sendBegin("A", "1", 1); try sto.sendDone("A", "1", 5); _ = try sto.sendBegin("B", "2", 6); try T.expect((try sto.lastSend(aren.allocator())) .? .len == 1); try sto.sendDone("B", "2", 9); try T.expectEqualStrings("B", (try sto.lastSend(aren.allocator())).?); }
test "undo last: recall the newest own message in the chat after force; needs force; dry previews" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); _ = try snd.sendText(&live, "Mom", "take this back"); try T.expectError(error.NeedForce, acts.recallLast(&live, "Mom")); var dry = rg.ses(rig.cfgOf(), .dry); dry.fake_ms += 600000; try T.expect(!try acts.recallLast(&dry, "Mom")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.recalled.length")); var frc = rg.ses(rig.cfgOf(), .force); frc.fake_ms += 1200000; try T.expect(try acts.recallLast(&frc, "Mom")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.recalled.length")); var again = rg.ses(rig.cfgOf(), .force); again.fake_ms += 1800000; try T.expectError(error.NoElem, acts.recallLast(&again, "Boss")); }
